/// Arsenal's patch: how many particles in a hundred Particle Limiter keeps, and a running count.
pub static ARSENAL_PARTICLES: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(100);
static ARSENAL_PARTICLE_COUNT: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);

/// Arsenal's patch: particles to hide (1 crits, 2 sweeps, 4 totem particles, 8 your own effect particles) and to
/// keep the places of (crits, sweeps, totem particles) for Arsenal to draw its own there.
pub static ARSENAL_HIDE: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);
pub static ARSENAL_CAPTURE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
pub static ARSENAL_CAUGHT: std::sync::Mutex<Vec<(&'static str, [f64; 3])>> = std::sync::Mutex::new(Vec::new());

/// Arsenal's patch: Particle Limiter keeps this many particles in a hundred (the rest are never made).
pub fn arsenal_keep() -> bool {
    let percent = ARSENAL_PARTICLES.load(std::sync::atomic::Ordering::Relaxed);
    percent >= 100 || ARSENAL_PARTICLE_COUNT.fetch_add(1, std::sync::atomic::Ordering::Relaxed) % 100 < percent
}

