/// What a native mod wants the game to look like for this player (Arsenal's patch). None leaves Horizon's own.
#[allow(dead_code)]
#[derive(Clone, Debug, Default)]
pub(crate) struct ArsenalVisuals {
    pub(crate) gamma: Option<f32>,
    pub(crate) fire_lower: Option<u8>,
    pub(crate) shield_size: Option<u8>,
    pub(crate) totem_size: Option<u8>,
    /// `red`, `blue`... or `vanilla`.
    pub(crate) glint: Option<String>,
    /// `morning`, `noon`, `sunset`, `midnight` or `world`.
    pub(crate) time: Option<String>,
    /// `clear`, `rain`, `thunder` or `world`.
    pub(crate) weather: Option<String>,
    /// The hit colour and how much of it covers (percent), or `vanilla`.
    pub(crate) hit: Option<(String, u8)>,
    pub(crate) no_hurt_cam: bool,
    pub(crate) no_pumpkin: bool,
    pub(crate) particles: u32,
    pub(crate) chat_hide: Vec<String>,
    /// Particles to hide (`horizon_client::particles::ARSENAL_HIDE`'s bits) and whether to keep crit / sweep places.
    pub(crate) hide_particles: u32,
    pub(crate) capture: bool,
}

/// The crit, sweep and totem particles made since the last call: (type, where) (Arsenal's patch).
pub(super) fn arsenal_particles(&self) -> Vec<(&'static str, [f64; 3])> {
    horizon_client::particles::ARSENAL_CAUGHT.lock().map(|mut c| std::mem::take(&mut *c)).unwrap_or_default()
}
/// The game's brightness option now (Arsenal's patch).
pub(super) fn arsenal_gamma(&self) -> f32 {
    self.settings.gamma
}
/// Applies what a native mod wants the game to look like (Arsenal's patch).
pub(super) fn arsenal_visuals(&mut self, v: &ArsenalVisuals) {
    use horizon_client::pvp::{Colour, ViewTime, ViewWeather};
    use std::sync::atomic::Ordering::Relaxed;
    let colour = |name: &str| match name {
        "white" => Some(Colour::White), "red" => Some(Colour::Red), "orange" => Some(Colour::Orange), "yellow" => Some(Colour::Yellow),
        "green" => Some(Colour::Green), "cyan" => Some(Colour::Cyan), "blue" => Some(Colour::Blue), "magenta" => Some(Colour::Magenta),
        "black" => Some(Colour::Black), "inverted" => Some(Colour::Inverted), _ => None,
    };
    if let Some(g) = v.gamma {
        self.settings.gamma = g;
    }
    let t = &mut self.settings.extras.pvp.tweaks;
    if let Some(x) = v.fire_lower { t.fire_lower = x; }
    if let Some(x) = v.shield_size { t.shield_size = x; }
    if let Some(x) = v.totem_size { t.totem_size = x; }
    if let Some(g) = &v.glint { t.glint = colour(g); }
    if let Some(time) = &v.time {
        t.time = match time.as_str() { "morning" => Some(ViewTime::Morning), "noon" => Some(ViewTime::Noon), "sunset" => Some(ViewTime::Sunset), "midnight" => Some(ViewTime::Midnight), _ => None };
    }
    if let Some(w) = &v.weather {
        t.weather = match w.as_str() { "clear" => Some(ViewWeather::Clear), "rain" => Some(ViewWeather::Rain), "thunder" => Some(ViewWeather::Thunder), _ => None };
    }
    if let Some((c, opacity)) = &v.hit {
        let h = &mut self.settings.extras.pvp.hit;
        match colour(c) {
            Some(c) => { h.custom = true; h.colour = c; h.opacity = *opacity; }
            None => h.custom = false,
        }
    }
    horizon_client::camera::ARSENAL_NO_HURT_CAM.store(v.no_hurt_cam, Relaxed);
    horizon_client::hud_overlays::ARSENAL_NO_PUMPKIN.store(v.no_pumpkin, Relaxed);
    horizon_client::particles::ARSENAL_PARTICLES.store(v.particles.min(100), Relaxed);
    horizon_client::particles::ARSENAL_HIDE.store(v.hide_particles, Relaxed);
    horizon_client::particles::ARSENAL_CAPTURE.store(v.capture, Relaxed);
    if let Ok(mut hide) = horizon_client::chat::ARSENAL_CHAT_HIDE.write() {
        if *hide != v.chat_hide {
            *hide = v.chat_hide.clone();
        }
    }
}
